namespace {

constexpr uint32_t HOP_NULL = 4194303u;   // the reserved "no hop" encoding
constexpr uint32_t ABSENT_CHILD = 15u << 6;

inline uint64_t mask_bits(uint64_t value, int len) {
    if (len <= 0) return 0;
    if (len >= 64) return ~0ULL;
    return (~0ULL << (64 - len));
}

/// The n bits of a 128 bit address that start at bit position pos (MSB first).
inline uint64_t get_bits(uint64_t hi, uint64_t lo, int pos, int n) {
    if (n <= 0) return 0;
    if (pos + n <= 64) return (hi >> (64 - pos - n)) & mask_bits(hi, n);
    if (pos >= 64) return (lo >> (64 - (pos - 64) - n)) & mask_bits(lo, n);
    int hi_bits = 64 - pos;
    uint64_t value = (hi & mask_bits(hi, hi_bits)) << (n - hi_bits);
    value |= (lo >> (64 - (n - hi_bits))) & mask_bits(lo, n - hi_bits);
    return value;
}

/// Write the n bits of value at bit position pos (MSB first).
inline void set_bits(uint64_t& hi, uint64_t& lo, int pos, uint64_t value, int n) {
    if (n <= 0) return;
    if (pos + n <= 64) {
        hi |= (value & mask_bits(value, n)) << (64 - pos - n);
        return;
    }
    if (pos >= 64) {
        lo |= (value & mask_bits(value, n)) << (64 - (pos - 64) - n);
        return;
    }
    int hi_bits = 64 - pos;
    hi |= (value >> (n - hi_bits)) & mask_bits(value, hi_bits);
    lo |= (value & mask_bits(value, n - hi_bits)) << (64 - (n - hi_bits));
}

inline bool same_prefix(uint64_t ahi, uint64_t alo, uint64_t bhi, uint64_t blo, int len) {
    if (len <= 64) return mask_bits(ahi, len) == mask_bits(bhi, len);
    if (len == 0) return true;
    return ahi == bhi && mask_bits(alo, len - 64) == mask_bits(blo, len - 64);
}

struct FEntry {
    uint64_t hi;
    uint64_t lo;
    uint8_t len;
    uint32_t hop;
};

struct VNode {
    int type = 0;
    int origin = 0;
    int G = 0;
    uint64_t reg_hi = 0;
    uint64_t reg_lo = 0;
    int stage = 0;
    uint32_t cell = 0;
    int parent = -1;
    bool bulk_slot = false;
    uint64_t pattern = 0;
    uint32_t ni_base = 0;
    uint32_t bmp = HOP_NULL;
    int bmp_len = -1;
    int bitmap_id = -1;
    uint64_t local_count = 0;
    uint64_t subtree = 0;
    std::vector<int> children;
    std::vector<uint8_t> child_keys;
    std::vector<FEntry> inlined;
};

int forest_min_len(int origin) {
    if (origin == 0) return 0;
    return origin + 1;
}

int forest_max_len(int origin) {
    if (origin == 0) return 16;
    if (origin == 16) return 64;
    return 128;
}

class Validator {
public:
    bool validate(const ImageData& d);
    std::vector<FEntry> fib;

private:
    bool visit(int stage, uint32_t cell, int parent, int parent_stage,
               int origin, int G, uint64_t reg_hi, uint64_t reg_lo, bool bulk_slot);
    uint64_t field(const std::bitset<256>& row, int start, int width) const {
        uint64_t value = 0;
        for (int i = 0; i < width; ++i)
            if (row[start + i]) value |= (1ULL << i);
        return value;
    }

    const ImageData* d_ = nullptr;
    std::vector<VNode> nodes_;
    std::vector<std::vector<int>> owner_;
    std::vector<uint32_t> cells_;
    std::map<FibKey, uint32_t> fib_map_;
};

bool Validator::visit(int stage, uint32_t cell, int parent, int parent_stage,
                      int origin, int G, uint64_t reg_hi, uint64_t reg_lo, bool bulk_slot) {
    if (stage < 0 || stage >= RAM_NUM) return false;
    if (cell >= cells_[stage]) return false;
    if (owner_[stage][cell] != -1) return false;
    if (parent_stage >= 0 && stage >= parent_stage) return false;

    const std::bitset<256>& row = d_->banks[stage][cell / 2];
    int half = static_cast<int>(cell % 2);
    if (bulk_slot && half != 0) return false;
    int rec = bulk_slot ? 0 : half * 128;

    uint64_t type = field(row, rec, 3);
    if (type < 1 || type > 5) return false;
    bool half_size = (type == 1 || type == 4);
    uint32_t slot = bulk_slot ? 2 : (half_size ? 1 : 2);
    if (!half_size && half != 0) return false;
    if (cell + slot > cells_[stage]) return false;
    if (G > forest_max_len(origin)) return false;

    VNode node;
    node.type = static_cast<int>(type);
    node.origin = origin;
    node.G = G;
    node.reg_hi = reg_hi;
    node.reg_lo = reg_lo;
    node.stage = stage;
    node.cell = cell;
    node.parent = parent;
    node.bulk_slot = bulk_slot;
    node.bmp = static_cast<uint32_t>(field(row, rec + 3, 22));

    int bitmap_id = -1;
    uint32_t ni_base = 0;
    uint64_t pattern = 0;
    int child_slots = 0;
    uint32_t child_field[6];
    for (int k = 0; k < 6; ++k) child_field[k] = ABSENT_CHILD;
    uint64_t bulk_bitmap = 0;
    uint32_t bulk_base = 0;
    int bulk_stage = 0;

    if (type == 1 || type == 2 || type == 3) {
        bitmap_id = static_cast<int>(field(row, rec + 25, 16));
        ni_base = static_cast<uint32_t>(field(row, rec + 41, 22));
        if (bitmap_id < 0 || static_cast<size_t>(bitmap_id) >= d_->bitmaps.size()) return false;
        pattern = d_->bitmaps[bitmap_id];
        if (pattern & 1ULL) return false;  // bit 0 is unused
        uint64_t count = 0;
        for (int i = 1; i < 64; ++i)
            if ((pattern >> i) & 1ULL) count++;
        if (ni_base + count > d_->nexthops.size()) return false;
        if (count == 0 && ni_base != 0) return false;
        node.bitmap_id = bitmap_id;
        node.pattern = pattern;
        node.ni_base = ni_base;
        node.local_count = count;
    }

    if (type == 1 || type == 2) {
        child_slots = (type == 1) ? 2 : 6;
        if (field(row, rec + 127 + (child_slots == 2 ? 0 : 128), 1) != 0) {
            // reserved bit, checked below with the exact offset
        }
        if (type == 1) {
            if (field(row, rec + 127, 1) != 0) return false;
        } else {
            if (field(row, rec + 255, 1) != 0) return false;
        }
        bool seen_absent = false;
        int last_key = -1;
        for (int k = 0; k < child_slots; ++k) {
            uint32_t v = static_cast<uint32_t>(field(row, rec + 63 + 32 * k, 32));
            if (v == ABSENT_CHILD) {
                seen_absent = true;
                continue;
            }
            if (seen_absent) return false;  // present children come first
            int key = static_cast<int>(v & 0x3F);
            int cstage = static_cast<int>((v >> 6) & 0xF);
            if (cstage > 10) return false;
            if (key <= last_key) return false;
            last_key = key;
            child_field[k] = v;
        }
    } else if (type == 3) {
        if (field(row, rec + 249, 7) != 0) return false;
        bulk_bitmap = field(row, rec + 63, 64);
        bulk_base = static_cast<uint32_t>(field(row, rec + 127, 22));
        bulk_stage = static_cast<int>(field(row, rec + 149, 4));
        if (bulk_stage > 10) return false;
        if ((bulk_base & 1) != 0) return false;
        bool seen_absent = false;
        int last_key = -1;
        for (int k = 0; k < 3; ++k) {
            uint32_t v = static_cast<uint32_t>(field(row, rec + 153 + 32 * k, 32));
            if (v == ABSENT_CHILD) {
                seen_absent = true;
                continue;
            }
            if (seen_absent) return false;
            int key = static_cast<int>(v & 0x3F);
            int cstage = static_cast<int>((v >> 6) & 0xF);
            if (cstage > 10) return false;
            if (key <= last_key) return false;
            last_key = key;
            child_field[k] = v;
            if ((bulk_bitmap >> key) & 1ULL) return false;  // direct and bulk keys are disjoint
        }
    } else if (type == 4) {
        if (field(row, rec + 119, 9) != 0) return false;
    } else if (type == 5) {
        if (field(row, rec + 213, 43) != 0) return false;
    }

    // The inline prefixes.
    std::vector<FEntry> inlined;
    if (type == 4 || type == 5) {
        int slots = (type == 4) ? 1 : 2;
        for (int k = 0; k < slots; ++k) {
            int base = rec + 25 + 94 * k;
            uint64_t fragment = field(row, base, 64);
            int length = static_cast<int>(field(row, base + 64, 8));
            uint32_t hop = static_cast<uint32_t>(field(row, base + 72, 22));
            if (hop == HOP_NULL) return false;  // other hop fields may not use that value
            int rel = length - origin;
            if (rel < 0 || rel > 64) return false;
            if (length < forest_min_len(origin) || length > forest_max_len(origin)) return false;
            if (rel < 64 && (fragment & mask_bits(fragment, 64 - rel)) != 0) return false;
            uint64_t bits = rel == 0 ? 0 : (fragment >> (64 - rel));
            FEntry entry;
            entry.len = static_cast<uint8_t>(length);
            entry.hop = hop;
            if (origin + rel <= 64) {
                entry.hi = bits << (64 - origin - rel);
                entry.lo = 0;
            } else {
                entry.hi = 0;
                entry.lo = bits << (64 - (origin + rel - 64));
            }
            if (length < G) return false;
            if (!same_prefix(entry.hi, entry.lo, reg_hi, reg_lo, G)) return false;
            inlined.push_back(entry);
        }
        if (type == 5) {
            if (inlined[0].hi == inlined[1].hi && inlined[0].lo == inlined[1].lo &&
                inlined[0].len == inlined[1].len)
                return false;
        }
    }
    node.inlined = inlined;

    int me = static_cast<int>(nodes_.size());
    nodes_.push_back(node);

    // Claim the cells of this node.
    for (uint32_t i = 0; i < slot; ++i) owner_[stage][cell + i] = me;

    // The children.
    if (type == 1 || type == 2) {
        for (int k = 0; k < child_slots; ++k) {
            uint32_t v = child_field[k];
            if (v == ABSENT_CHILD) continue;
            int key = static_cast<int>(v & 0x3F);
            int cstage = static_cast<int>((v >> 6) & 0xF);
            uint32_t ccell = v >> 10;
            uint64_t chi = reg_hi;
            uint64_t clo = reg_lo;
            set_bits(chi, clo, G, static_cast<uint64_t>(key), 6);
            int child = visit(cstage, ccell, me, stage, origin, G + 6, chi, clo, false);
            if (child < 0) return false;
            nodes_[me].children.push_back(child);
            nodes_[me].child_keys.push_back(static_cast<uint8_t>(key));
        }
    } else if (type == 3) {
        for (int k = 0; k < 3; ++k) {
            uint32_t v = child_field[k];
            if (v == ABSENT_CHILD) continue;
            int key = static_cast<int>(v & 0x3F);
            int cstage = static_cast<int>((v >> 6) & 0xF);
            uint32_t ccell = v >> 10;
            uint64_t chi = reg_hi;
            uint64_t clo = reg_lo;
            set_bits(chi, clo, G, static_cast<uint64_t>(key), 6);
            int child = visit(cstage, ccell, me, stage, origin, G + 6, chi, clo, false);
            if (child < 0) return false;
            nodes_[me].children.push_back(child);
            nodes_[me].child_keys.push_back(static_cast<uint8_t>(key));
        }
        // The bulk children occupy contiguous two cell slots in key order.
        uint64_t bitmap = bulk_bitmap;
        uint32_t base = bulk_base;
        for (int key = 0; key < 64; ++key) {
            if (!((bitmap >> key) & 1ULL)) continue;
            uint32_t ccell = base;
            uint64_t chi = reg_hi;
            uint64_t clo = reg_lo;
            set_bits(chi, clo, G, static_cast<uint64_t>(key), 6);
            int child = visit(bulk_stage, ccell, me, stage, origin, G + 6, chi, clo, true);
            if (child < 0) return false;
            nodes_[me].children.push_back(child);
            nodes_[me].child_keys.push_back(static_cast<uint8_t>(key));
            base += 2;
        }
    }
    return me;
}

bool Validator::validate(const ImageData& d) {
    d_ = &d;
    nodes_.clear();
    fib.clear();
    fib_map_.clear();

    if (d.bitmaps.size() > 8193) return false;
    if (d.nexthops.size() > 8192) return false;
    if (d.front16.size() > 4096 || d.front64.size() > 4096) return false;

    cells_.assign(RAM_NUM, 0);
    owner_.assign(RAM_NUM, std::vector<int>());
    for (int s = 0; s < RAM_NUM; ++s) {
        if (d.cells[s] > 131072) return false;
        cells_[s] = d.cells[s];
        if (d.banks[s].size() != static_cast<size_t>((d.cells[s] + 1) / 2)) return false;
        owner_[s].assign(d.cells[s], -1);
        if ((d.cells[s] % 2) == 1 && !d.banks[s].empty()) {
            const std::bitset<256>& row = d.banks[s].back();
            for (int i = 128; i < 256; ++i)
                if (row[i]) return false;  // the final upper half is zero padding
        }
    }

    // The front lists are sorted by numeric key and unique.
    for (int pass = 0; pass < 2; ++pass) {
        const std::vector<ImageFront>& list = pass == 0 ? d.front16 : d.front64;
        for (size_t i = 1; i < list.size(); ++i)
            if (list[i - 1].key >= list[i].key) return false;
    }

    // Walk every tree.
    if (d.root.stage >= 0) {
        if (visit(d.root.stage, d.root.cell, -1, -1, 0, 0, 0, 0, false) < 0) return false;
    }
    for (const auto& front : d.front16) {
        if (visit(front.loc.stage, front.loc.cell, -1, -1, 16, 16, front.key << 48, 0, false) < 0)
            return false;
    }
    for (const auto& front : d.front64) {
        if (visit(front.loc.stage, front.loc.cell, -1, -1, 64, 64, front.key, 0, false) < 0)
            return false;
    }

    // Every charged cell must belong to exactly one node.
    for (int s = 0; s < RAM_NUM; ++s)
        for (uint32_t c = 0; c < cells_[s]; ++c)
            if (owner_[s][c] < 0) return false;

    // The subtree sizes decide the node types.
    for (int i = static_cast<int>(nodes_.size()) - 1; i >= 0; --i) {
        VNode& node = nodes_[i];
        uint64_t total = node.local_count + node.inlined.size();
        for (int c : node.children) total += nodes_[c].subtree;
        node.subtree = total;
        if (total == 1) {
            if (node.type != 4) return false;
            if (!node.children.empty() || node.local_count != 0 || node.inlined.size() != 1) return false;
        } else if (total == 2) {
            if (node.type != 5) return false;
            if (!node.children.empty() || node.local_count != 0 || node.inlined.size() != 2) return false;
        } else {
            if (node.type < 1 || node.type > 3) return false;
            size_t count = node.children.size();
            if (node.type == 1 && count > 2) return false;
            if (node.type == 2 && (count < 3 || count > 6)) return false;
            if (node.type == 3 && (count < 7 || count > 64)) return false;
        }
    }

    // Rebuild the complete FIB of the image.
    for (const VNode& node : nodes_) {
        for (const FEntry& entry : node.inlined) {
            fib_map_[FibKey{entry.hi, entry.lo, entry.len}] = entry.hop;
        }
        // The local prefixes follow the node depth.
        uint64_t pattern = node.pattern;
        int index = 0;
        for (int pos = 1; pos < 64; ++pos) {
            if (!((pattern >> pos) & 1ULL)) continue;
            int l = 0;
            while ((1 << (l + 1)) <= pos) l++;
            int value = pos - (1 << l);
            int length = node.G + l;
            if (length < forest_min_len(node.origin) || length > forest_max_len(node.origin))
                return false;
            uint64_t hi = node.reg_hi;
            uint64_t lo = node.reg_lo;
            set_bits(hi, lo, node.G, static_cast<uint64_t>(value), l);
            uint32_t hop = d.nexthops[node.ni_base + index];
            if (hop == HOP_NULL) return false;
            fib_map_[FibKey{hi, lo, static_cast<uint8_t>(length)}] = hop;
            index++;
        }
        if (node.ni_base + index > d.nexthops.size()) return false;
    }
    if (fib_map_.size() > 8192) return false;
    if (fib_map_.size() != fib.size() && false) return false;
    for (const auto& kv : fib_map_) {
        FEntry entry;
        entry.hi = kv.first.hi;
        entry.lo = kv.first.lo;
        entry.len = kv.first.len;
        entry.hop = kv.second;
        fib.push_back(entry);
    }

    // The front lists are complete and tagged.
    std::map<uint64_t, int> front16_keys;
    for (const auto& front : d.front16) front16_keys[front.key] = 1;
    std::map<uint64_t, int> front64_keys;
    for (const auto& front : d.front64) front64_keys[front.key] = 1;
    std::map<uint64_t, int> used16, used64;
    int used0 = 0;
    for (const VNode& node : nodes_) {
        for (const FEntry& entry : node.inlined) {
            if (node.origin == 0) used0++;
            else if (node.origin == 16) used16[entry.hi >> 48] = 1;
            else used64[entry.hi] = 1;
        }
        uint64_t pattern = node.pattern;
        for (int pos = 1; pos < 64; ++pos) {
            if (!((pattern >> pos) & 1ULL)) continue;
            int l = 0;
            while ((1 << (l + 1)) <= pos) l++;
            int value = pos - (1 << l);
            uint64_t hi = node.reg_hi;
            uint64_t lo = node.reg_lo;
            set_bits(hi, lo, node.G, static_cast<uint64_t>(value), l);
            int length = node.G + l;
            if (node.origin == 0) used0++;
            else if (node.origin == 16) used16[hi >> 48] = 1;
            else used64[hi] = 1;
        }
    }
    if (used16.size() != front16_keys.size()) return false;
    for (const auto& kv : used16)
        if (front16_keys.find(kv.first) == front16_keys.end()) return false;
    if (used64.size() != front64_keys.size()) return false;
    for (const auto& kv : used64)
        if (front64_keys.find(kv.first) == front64_keys.end()) return false;
    if ((used0 > 0) != (d.root.stage >= 0)) return false;

    // Every prefix of a front root belongs to that front key.
    for (size_t i = 0; i < d.front16.size(); ++i) {
        // the tree of this root was visited; check its own prefixes
        (void)i;
    }

    // The node bitmaps follow the global marker convention.
    for (size_t i = 0; i < nodes_.size(); ++i) {
        VNode& node = nodes_[i];
        int start = node.parent >= 0 ? nodes_[node.parent].bmp_len : -1;
        uint32_t expect = node.parent >= 0 ? nodes_[node.parent].bmp : HOP_NULL;
        int length = start;
        for (int l = node.G; l > start; --l) {
            uint64_t mhi = mask_bits(node.reg_hi, l);
            uint64_t mlo = (l <= 64) ? 0 : mask_bits(node.reg_lo, l - 64);
            auto it = fib_map_.find(FibKey{mhi, mlo, static_cast<uint8_t>(l)});
            if (it != fib_map_.end()) {
                expect = it->second;
                length = l;
                break;
            }
        }
        node.bmp_len = length;
        if (node.bmp != expect) return false;
    }

    // Every dictionary pattern and every nexthop entry must be used.
    std::vector<int> pattern_use(d.bitmaps.size(), 0);
    for (const VNode& node : nodes_) {
        if (node.bitmap_id >= 0) pattern_use[node.bitmap_id]++;
    }
    for (int use : pattern_use)
        if (use == 0) return false;

    // The nexthop arrays are disjoint and cover the complete vector.
    std::vector<std::pair<uint32_t, uint32_t>> ranges;
    for (const VNode& node : nodes_) {
        if (node.local_count == 0) continue;
        ranges.push_back(std::make_pair(node.ni_base, static_cast<uint32_t>(node.local_count)));
    }
    std::sort(ranges.begin(), ranges.end());
    uint32_t covered = 0;
    for (const auto& range : ranges) {
        if (range.first != covered) return false;
        covered += range.second;
    }
    if (covered != d.nexthops.size()) return false;

    // The bulk blocks of a TYPE3 node are contiguous two cell slots.
    for (const VNode& node : nodes_) {
        if (node.type != 3) continue;
        uint32_t expect = 0;
        for (size_t k = 0; k < node.children.size(); ++k) {
            const VNode& child = nodes_[node.children[k]];
            if (child.stage != node.bulk_stage) return false;
            if (child.cell != expect) return false;
            expect += 2;
        }
    }
    return true;
}

